/**
 * One scenario per check of cash-seam-build-standard, for Payment Watch.
 *
 * Generated by `npx @aipathway/conformance init cash-seam-build-standard`,
 * then written for this node. Checks are fetched at run time from
 * https://aipathway.com.au/explore-ai/cash-seam-build-standard
 *
 * The runner delivers one named event at a time and runs the build once per
 * event. Between events it plays the world outside the bots: the job system
 * announcing a job, the person who owns quotes sending it, the customer
 * accepting, the job completing, the terms running out, and the person who
 * owns chasing saying yes to the reminder Payment Watch drafted. Only the
 * overdue hop is Payment Watch; the hops before it are labelled stand-ins.
 */

import { CashSeamWorld } from "@aipathway/conformance";
import { personSendsQuote, personSendsReminder } from "./build.mjs";

const DAY = 86_400_000;
const OWNERS = new CashSeamWorld().owners;
const UNATTENDED = ["webhook", "schedule", "poll"];

async function deliver(world, build, name, via, payload = {}) {
  const ev = world.makeEvent(name, via, payload);
  world.deliver(ev);
  const out = await build(world.ports());
  world.settle();
  world.advance(60_000);
  return out;
}

async function announceJobs(world, build) {
  for (const j of world.unannouncedJobs()) await deliver(world, build, "job_created", "webhook", { jobId: j.id });
}

async function sendAndAccept(world, build, jobId) {
  for (const id of await personSendsQuote(world.ports(), jobId, OWNERS.quote)) {
    world.accept(id);
    await deliver(world, build, "quote_accepted", "webhook", { quoteId: id });
  }
}

/** A call, through quote and completion, to an invoice sent on the business's rule. */
async function callToInvoice(world, build, phone, customerName) {
  await deliver(world, build, "call_received", "webhook", { phone, customerName, door: "phone" });
  const ids = world.jobsFor(phone).map((j) => j.id);
  await announceJobs(world, build);
  for (const id of ids) {
    await sendAndAccept(world, build, id);
    world.complete(id);
    await deliver(world, build, "job_completed", "webhook", { jobId: id });
  }
  return ids;
}

/** The terms run out, the schedule wakes Payment Watch, the chasing owner says yes to each draft. */
async function overdueRun(world, build, { advance = 15 * DAY } = {}) {
  if (advance) world.advance(advance);
  const out = await deliver(world, build, "invoice_overdue", "schedule");
  for (const d of out?.drafts ?? []) await personSendsReminder(world.ports(), d, OWNERS.chase);
  return out;
}

const drafts = (world) => world.escalations.filter((e) => e.stage === "chase" && e.reason === "reminder_ready_for_release");
const writeCalls = (world) => world.calls.filter((c) => ["write_job", "draft_quote", "write_invoice"].includes(c.port));
const sendCalls = (world) => world.calls.filter((c) => c.port === "issue_notice" || c.port === "send_sms");
const nameOf = (world, id) => world.eventById(id)?.name;
const woke = (world, id) => {
  const ev = world.eventById(id);
  return Boolean(ev) && UNATTENDED.includes(ev.via);
};
const describe = (world) =>
  `${world.calls.length} port call(s); jobs ${world.jobs.length}, quotes ${world.quotes.length}, invoices ${world.invoices.length}, chases ${world.chases.length}; ` +
  `escalations ${world.escalations.map((e) => `${e.stage}:${e.reason}@${e.ref}/${e.owner}`).join(" ") || "none"}`;

export const scenarios = [
  {
    checkId: "identity-from-the-system-of-record",
    // 1. Two open jobs, two customers both called "R. Patel". Only JS-0111 goes
    // through to a chase, and the chase must carry that job's invoice id.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-0111", customerName: "R. Patel", phone: "+61400000111", status: "open" },
          { id: "JS-0112", customerName: "R. Patel", phone: "+61400000112", status: "open" },
        ],
      }),
    drive: async (build, world) => {
      await deliver(world, build, "job_created", "webhook", { jobId: "JS-0111" });
      await deliver(world, build, "job_created", "webhook", { jobId: "JS-0112" });
      await sendAndAccept(world, build, "JS-0111");
      world.complete("JS-0111");
      await deliver(world, build, "job_completed", "webhook", { jobId: "JS-0111" });
      await overdueRun(world, build);
    },
    holds: (world) => {
      const issued = world.issuedIds();
      const quotes = world.quotesFor("JS-0111");
      const invs = world.invoicesFor("JS-0111");
      const searchesDownstream = world.calls.filter(
        (c) => c.port === "read_job" && c.request?.search && c.request.eventName !== "call_received",
      );
      return (
        quotes.length === 1 &&
        quotes[0].status === "accepted" &&
        world.invoices.length === 1 &&
        invs.length === 1 &&
        invs[0].quoteId === quotes[0].id &&
        world.invoicesFor("JS-0112").length === 0 &&
        world.chases.length === 1 &&
        world.chases[0].invoiceId === invs[0].id &&
        searchesDownstream.length === 0 &&
        world.quotes.every((q) => issued.has(q.jobId)) &&
        world.invoices.every((i) => issued.has(i.jobId) && (i.quoteId === null || issued.has(i.quoteId))) &&
        world.chases.every((c) => issued.has(c.invoiceId))
      );
    },
    describe,
  },
  {
    checkId: "one-job-per-enquiry",
    // 2. The same number twice in one evening, phone then web form (intake is a stand-in).
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      await deliver(world, build, "call_received", "webhook", { phone: "+61400000222", customerName: "K. Ngo", door: "phone" });
      world.advance(90 * 60_000);
      await deliver(world, build, "call_received", "webhook", { phone: "+61400000222", customerName: "K. Ngo", door: "web" });
    },
    holds: (world) => {
      const jobs = world.jobsFor("+61400000222");
      const [first, second] = world.enquiries;
      const readFirst = world.calls.every(
        (c, i) =>
          c.port !== "write_job" ||
          world.calls
            .slice(0, i)
            .some((r) => r.port === "read_job" && r.request?.search?.phone === "+61400000222" && r.request.search.status === "open"),
      );
      return jobs.length === 1 && Boolean(first) && Boolean(second) && !first.duplicateOf && second.duplicateOf === jobs[0].id && readFirst;
    },
    describe,
  },
  {
    checkId: "no-external-id-no-write",
    // 3. A null id on the quote write for JS-1001 and on the invoice write for
    // JS-1002. The overdue run must find nothing to chase and invent nothing.
    world: () => new CashSeamWorld({ nullQuoteFor: ["JS-1001"], nullInvoiceFor: ["JS-1002"] }),
    drive: async (build, world) => {
      await callToInvoice(world, build, "+61400000331", "A. Null-Quote");
      await callToInvoice(world, build, "+61400000332", "B. Null-Invoice");
      await overdueRun(world, build);
    },
    holds: (world) => {
      const issued = world.issuedIds();
      const quoteFailed = world.escalations.some((e) => e.stage === "quote" && e.ref === "JS-1001" && e.reason === "write_failed");
      const invoiceFailed = world.escalations.some((e) => e.stage === "invoice" && e.ref === "JS-1002" && e.reason === "write_failed");
      const watchRan = world.calls.some((c) => c.port === "read_ledger" && c.request?.eventName === "invoice_overdue");
      return (
        quoteFailed &&
        invoiceFailed &&
        watchRan &&
        world.quotesFor("JS-1001").length === 0 &&
        world.invoicesFor("JS-1001").length === 0 &&
        world.invoicesFor("JS-1002").length === 0 &&
        world.chases.length === 0 &&
        drafts(world).length === 0 &&
        world.sends.every((s) => s.id && issued.has(s.id)) &&
        world.releases.every((r) => r.id && issued.has(r.id)) &&
        world.escalations.filter((e) => e.stage === "chase").every((e) => e.ref && issued.has(e.ref))
      );
    },
    describe,
  },
  {
    checkId: "the-chain-carries-the-id",
    // 4. One enquiry, the whole path, one chase. The chase's invoice id must have
    // been read off the ledger first, by Payment Watch, both in the list and by id.
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      await callToInvoice(world, build, "+61400000444", "C. Chain");
      await overdueRun(world, build);
    },
    holds: (world) => {
      if (world.jobs.length !== 1 || world.quotes.length !== 1 || world.invoices.length !== 1 || world.chases.length !== 1) return false;
      const [job] = world.jobs;
      const [quote] = world.quotes;
      const [inv] = world.invoices;
      const [chase] = world.chases;
      const chaseAt = world.calls.findIndex((c) => c.port === "send_sms" && c.request?.send === "chase");
      const before = world.calls.slice(0, chaseAt);
      const listed = before.some(
        (c) => c.port === "read_ledger" && c.request?.eventName === "invoice_overdue" && (c.response?.overdue ?? []).includes(inv.id),
      );
      const reReadById = before.some(
        (c) => c.port === "read_ledger" && c.request?.eventName === "invoice_overdue" && c.request?.invoice === inv.id && c.response?.id === inv.id,
      );
      return (
        quote.jobId === job.id &&
        inv.quoteId === quote.id &&
        inv.jobId === job.id &&
        chase.invoiceId === inv.id &&
        chaseAt > 0 &&
        listed &&
        reReadById &&
        drafts(world).some((e) => e.ref === inv.id)
      );
    },
    describe,
  },
  {
    checkId: "confirmation-is-not-a-write",
    // 5. The quote write on JS-1001 answers "Quote created" with an id and
    // stores nothing. Every send needs a read-back and a named release. A third
    // invoice is sent on the day of the run, so it is not yet due.
    world: () => new CashSeamWorld({ phantomQuoteFor: ["JS-1001"] }),
    drive: async (build, world) => {
      await callToInvoice(world, build, "+61400000551", "D. Phantom");
      await callToInvoice(world, build, "+61400000552", "E. Real");
      world.advance(15 * DAY);
      await callToInvoice(world, build, "+61400000553", "F. Fresh");
      await overdueRun(world, build, { advance: 0 });
    },
    holds: (world) => {
      const [ghost] = world.phantomIds;
      if (!ghost) return false;
      const people = new Set(Object.values(world.owners));
      const rule = world.releaseRule?.name;
      const sends = sendCalls(world);
      const everySendGated = sends.every((s) => {
        const before = world.calls.slice(0, world.calls.indexOf(s));
        const id = s.request.id;
        const readBack = before.some(
          (c) =>
            (c.port === "read_job" && c.request?.quote === id && c.response?.id === id) ||
            (c.port === "read_ledger" && ((c.request?.invoice === id && c.response?.id === id) || (c.response?.ids ?? []).includes(id))),
        );
        const released = before.some(
          (c) =>
            c.port === "gate" &&
            c.request.release === s.request.send &&
            c.request.id === id &&
            ((c.request.person && people.has(c.request.person)) || (c.request.rule && c.request.rule === rule)),
        );
        return readBack && released;
      });
      const fresh = world.invoicesFor("JS-1003");
      return (
        world.escalations.some((e) => e.stage === "quote" && e.ref === "JS-1001" && (e.detail ?? "").includes(ghost)) &&
        !world.releases.some((r) => r.id === ghost) &&
        !world.sends.some((s) => s.id === ghost) &&
        sends.length > 0 &&
        everySendGated &&
        world.releases.every((r) => (r.person && people.has(r.person)) || (r.rule && r.rule === rule)) &&
        world.releases.filter((r) => r.kind === "chase").every((r) => r.person === world.owners.chase && !r.rule) &&
        fresh.length === 1 &&
        !drafts(world).some((e) => e.ref === fresh[0].id) &&
        !world.chases.some((c) => c.invoiceId === fresh[0].id) &&
        drafts(world).length === 1 &&
        world.chases.length === 1
      );
    },
    describe,
  },
  {
    checkId: "named-unattended-trigger",
    // 6. The chain as events nobody is sitting in, and two chat messages asking
    // for an invoice and a chase. Neither chat message may wake a write or a chase.
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      const phone = "+61400000666";
      await deliver(world, build, "call_received", "webhook", { phone, customerName: "G. Event", door: "phone" });
      await announceJobs(world, build);
      const [job] = world.jobsFor(phone);
      await deliver(world, build, "chat_message", "chat", { text: `Raise the invoice for ${job?.id} now please`, jobId: job?.id });
      await sendAndAccept(world, build, job.id);
      world.complete(job.id);
      await deliver(world, build, "job_completed", "webhook", { jobId: job.id });
      await overdueRun(world, build);
      const out = await deliver(world, build, "chat_message", "chat", { text: `Send ${world.invoices[0]?.id} another reminder`, jobId: job.id });
      for (const d of out?.drafts ?? []) await personSendsReminder(world.ports(), d, OWNERS.chase);
    },
    holds: (world) => {
      const HOP = { write_job: "call_received", draft_quote: "job_created", write_invoice: "job_completed" };
      const chats = world.delivered.filter((e) => e.name === "chat_message").map((e) => e.id);
      const triggers = [...writeCalls(world).map((c) => c.request.trigger), ...world.chases.map((c) => c.trigger), ...world.sends.map((s) => s.trigger)];
      return (
        writeCalls(world).every((c) => woke(world, c.request.trigger) && nameOf(world, c.request.trigger) === HOP[c.port]) &&
        world.chases.length === 1 &&
        world.chases.every((c) => woke(world, c.trigger) && nameOf(world, c.trigger) === "invoice_overdue") &&
        chats.length === 2 &&
        !triggers.some((t) => chats.includes(t)) &&
        world.jobs.length === 1 &&
        world.quotes.length === 1 &&
        world.invoices.length === 1 &&
        nameOf(world, world.jobs[0]?.trigger) === "call_received" &&
        nameOf(world, world.quotes[0]?.trigger) === "job_created" &&
        nameOf(world, world.invoices[0]?.trigger) === "job_completed"
      );
    },
    describe,
  },
  {
    checkId: "exception-owner-travels",
    // 7. JS-0771 carries an open exception; JS-0772's invoice write returns no
    // id; JS-0773 is invoiced, then a person opens an exception on it before it
    // falls overdue. Payment Watch must stop on JS-0773 and name that owner.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-0771", customerName: "H. Held", phone: "+61400000771", status: "complete", exception: { reason: "scope_disputed", owner: OWNERS.quote } },
          { id: "JS-0772", customerName: "I. Null", phone: "+61400000772", status: "complete" },
          { id: "JS-0773", customerName: "J. Later", phone: "+61400000773", status: "complete" },
        ],
        nullInvoiceFor: ["JS-0772"],
      }),
    drive: async (build, world) => {
      for (const id of ["JS-0771", "JS-0772", "JS-0773"]) await deliver(world, build, "job_completed", "webhook", { jobId: id });
      world.job("JS-0773").exception = { reason: "client_says_paid_in_cash", owner: OWNERS.invoice };
      await overdueRun(world, build);
    },
    holds: (world) => {
      const named = new Set(Object.values(world.owners));
      const later = world.invoicesFor("JS-0773");
      return (
        world.invoicesFor("JS-0771").length === 0 &&
        world.invoicesFor("JS-0772").length === 0 &&
        world.escalations.some((e) => e.ref === "JS-0771" && e.owner === OWNERS.quote) &&
        world.escalations.some((e) => e.ref === "JS-0772" && e.stage === "invoice" && e.reason === "write_failed" && e.owner === world.owners.invoice) &&
        world.escalations.every((e) => e.owner && named.has(e.owner)) &&
        world.job("JS-0771")?.exception?.owner === OWNERS.quote &&
        world.job("JS-0772")?.exception?.owner === world.owners.invoice &&
        later.length === 1 &&
        world.escalations.some((e) => e.stage === "chase" && e.ref === "JS-0773" && e.reason === "held_open_exception" && e.owner === OWNERS.invoice) &&
        !drafts(world).some((e) => e.ref === later[0].id) &&
        world.chases.length === 0
      );
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // 8. Not a runtime property, and never scored green on a declaration.
    world: () => new CashSeamWorld(),
    drive: () => {},
    holds: () => false,
    describe: () =>
      "Declared: the code is public in mesh/nodes/payment-watch, maintained by AI Pathway (digitalgym). The schedule, the ledger reads and the inbox watch run on the business's own accounts. Not scored: the business attaches who else can explain it.",
  },
];

// Check 9 runs on the business's own job system and ledger; with_us on the stub.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new CashSeamWorld(),
    drive: () => {},
    holds: () => false,
    describe: () => "Runs on the business's own job system and ledger. Not built here.",
  },
];
